use schemars::JsonSchema;
use serde::{Deserialize, Serialize};
use std::collections::HashSet;

/// One person from the input file. IDs must be nonempty and unique.
#[derive(Debug, Deserialize, Serialize)]
#[serde(deny_unknown_fields)]
pub struct Attendee {
    /// A stable identifier copied into the agent's answer.
    pub id: String,
    /// Display name, taken from this roster rather than generated by the agent.
    pub name: String,
    /// Natural-language availability for the shared meeting week.
    pub availability: String,
}

/// A weekday in the shared, notional meeting week.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Deserialize, Serialize, JsonSchema)]
#[serde(rename_all = "lowercase")]
#[schemars(inline)]
pub enum Day {
    Monday,
    Tuesday,
    Wednesday,
    Thursday,
    Friday,
}
impl Day {
    /// Weekdays in solver index order, Monday through Friday.
    pub const ALL: [Self; 5] = [
        Self::Monday,
        Self::Tuesday,
        Self::Wednesday,
        Self::Thursday,
        Self::Friday,
    ];

    pub(crate) fn index(self) -> i64 {
        Self::ALL.iter().position(|day| *day == self).unwrap() as i64
    }
}
impl std::fmt::Display for Day {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        f.write_str(match self {
            Self::Monday => "Monday",
            Self::Tuesday => "Tuesday",
            Self::Wednesday => "Wednesday",
            Self::Thursday => "Thursday",
            Self::Friday => "Friday",
        })
    }
}

/// A half-open availability interval: start is included, end is excluded.
#[derive(Debug, Deserialize, Serialize, JsonSchema)]
#[serde(deny_unknown_fields)]
#[schemars(inline)]
pub struct TimeWindow {
    /// Weekday in the shared timezone.
    pub day: Day,
    /// First available hour, from 0 through 23, inclusive.
    pub start_hour: i64,
    /// End of availability, from 1 through 24, exclusive; greater than start_hour.
    pub end_hour: i64,
}

/// The agent's interpretation for exactly one original attendee ID.
#[derive(Debug, Deserialize, Serialize, JsonSchema)]
#[serde(deny_unknown_fields)]
#[schemars(inline)]
pub struct AttendeeAvailability {
    /// Copy an ID from the original roster; do not invent or change it.
    pub attendee_id: String,
    /// Available intervals; an empty list means this person cannot attend.
    pub windows: Vec<TimeWindow>,
}

/// The first typed answer: one availability record per input attendee.
#[derive(Debug, Deserialize, Serialize, JsonSchema)]
#[serde(deny_unknown_fields)]
pub struct ParsedAvailability {
    /// One entry per original roster ID; checked by `validate_availability`.
    pub attendees: Vec<AttendeeAvailability>,
}

/// The second typed answer. It cannot change the canonical schedule.
#[derive(Debug, Deserialize, JsonSchema)]
#[serde(deny_unknown_fields)]
pub struct Explanation {
    /// A short explanation of the supplied solver outcome, without inventing availability.
    pub explanation: String,
}

/// A one-hour meeting beginning at an integer hour in the shared timezone.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct Slot {
    pub day: Day,
    pub start_hour: i64,
}

/// Availability that has passed the application's roster and range checks.
///
/// Its fields are private so solving cannot accidentally bypass validation.
#[derive(Debug)]
pub struct ValidatedAvailability(pub(crate) ParsedAvailability);
impl ValidatedAvailability {
    /// The checked extraction, for display or inspection.
    pub fn parsed(&self) -> &ParsedAvailability {
        &self.0
    }

    /// Independently check a whole meeting against all windows and business hours.
    pub fn permits(&self, slot: Slot) -> bool {
        if !(9..17).contains(&slot.start_hour) {
            return false;
        }
        let end_hour = slot.start_hour + 1;
        self.0.attendees.iter().all(|attendee| {
            attendee.windows.iter().any(|window| {
                window.day == slot.day
                    && window.start_hour <= slot.start_hour
                    && end_hour <= window.end_hour
            })
        })
    }
}

/// Reject an empty roster, duplicate/empty IDs, and missing names or descriptions.
pub fn validate_roster(roster: &[Attendee]) -> crate::Result<()> {
    if roster.is_empty() {
        return Err("the roster must contain at least one attendee".into());
    }
    let mut ids = HashSet::new();
    for attendee in roster {
        if attendee.id.trim().is_empty() || !ids.insert(&attendee.id) {
            return Err(
                format!("attendee ID must be nonempty and unique: {:?}", attendee.id).into(),
            );
        }
        if attendee.name.trim().is_empty() || attendee.availability.trim().is_empty() {
            return Err(format!("attendee {:?} needs a name and availability", attendee.id).into());
        }
    }
    Ok(())
}

/// Check domain rules that JSON shape validation alone cannot establish.
pub fn validate_availability(
    roster: &[Attendee],
    parsed: ParsedAvailability,
) -> crate::Result<ValidatedAvailability> {
    validate_roster(roster)?;
    let expected: HashSet<_> = roster.iter().map(|attendee| attendee.id.as_str()).collect();
    let mut seen = HashSet::new();
    for attendee in &parsed.attendees {
        if !expected.contains(attendee.attendee_id.as_str()) {
            return Err(format!("unknown attendee ID: {:?}", attendee.attendee_id).into());
        }
        if !seen.insert(attendee.attendee_id.as_str()) {
            return Err(format!(
                "duplicate attendee ID in extraction: {:?}",
                attendee.attendee_id
            )
            .into());
        }
        for window in &attendee.windows {
            if !(0..24).contains(&window.start_hour)
                || !(1..=24).contains(&window.end_hour)
                || window.start_hour >= window.end_hour
            {
                return Err(format!(
                    "invalid window for {:?}: {} {}–{}",
                    attendee.attendee_id, window.day, window.start_hour, window.end_hour
                )
                .into());
            }
        }
    }
    if seen != expected {
        return Err("extraction must include every attendee exactly once".into());
    }
    Ok(ValidatedAvailability(parsed))
}
